function onInput(prev, raw, at, inputType){
  if (dateDigits(raw).length === dateDigits(prev).length && raw.length < prev.length) {
    if (inputType==='deleteContentBackward' && at>0){ raw = raw.slice(0,at-1)+raw.slice(at); at-=1; }
    else if (inputType==='deleteContentForward'){ raw = raw.slice(0,at)+raw.slice(at+1); }
  }
  return maskDateDigits(raw, at);
}
