function bs(t,c){ if(c===0) return null; return onInput(t, t.slice(0,c-1)+t.slice(c), c-1, 'deleteContentBackward'); }
function del(t,c){ if(c>=t.length) return null; return onInput(t, t.slice(0,c)+t.slice(c+1), c, 'deleteContentForward'); }
function type(t,s,e,ch){ const raw=t.slice(0,s)+ch+t.slice(e); if (raw.length>10 && e===s) return {blocked:true,text:t,caret:s}; const r = raw.length>10 ? t.slice(0,s)+ch.slice(0,10-(t.length-(e-s)))+t.slice(e) : raw; const c = s + (r.length - (t.length-(e-s))); return onInput(t, r, c, 'insertText'); }
