let r=type(D,0,2,'1'); show(' then type 6', type(r.text,r.caret,r.caret,'6'));
show('select month 05 type 1', type(D,3,5,'1'));
r=type(D,3,5,'1'); show(' then type 2', type(r.text,r.caret,r.caret,'2'));
show('select year type 2', type(D,6,10,'2'));
show('insert 6 at 1 (full)', type(D,1,1,'6'));
// bypass maxlength via pure fn
show('pure insert 6 at1', maskDateDigits('165/05/1990',2));
show('pure insert at 0', maskDateDigits('615/05/1990',1));
show('pure paste 12 at 3', maskDateDigits('15/1205/1990',5));
// correction flows
r=bs(D,2); show('BS day digit', r); show(' type 6', type(r.text,r.caret,r.caret,'6'));
r=bs(D,5); show('BS month digit', r); show(' type 6', type(r.text,r.caret,r.caret,'6'));
r=bs(D,3); show('BS after slash', r); show(' type 6', type(r.text,r.caret,r.caret,'6'));
r=del(D,2); show('DEL on slash', r);
// end typing
let t='',c=0; for (const ch of '15051990'){ r=type(t,c,c,ch); t=r.text;c=r.caret; } show('type 15051990', r);
t='';c=0; for (const ch of '5/5/1990'){ r=type(t,c,c,ch); t=r.text;c=r.caret; process.stdout.write(t+' | ');} show('type 5/5/1990', r);
t='';c=0; for (const ch of '15/05/1990'){ r=type(t,c,c,ch); t=r.text;c=r.caret; process.stdout.write(t+' | ');} show('type 15/05/1990', r);
t=D;c=10; for (let i=0;i<4;i++){ r=bs(t,c); t=r.text;c=r.caret; process.stdout.write(t+' | ');} show('4xBS', r);
show('fill 15.05.1990', onInput('', '15.05.1990', 10, 'insertText'));
show('fill 5/5/1990', onInput('', '5/5/1990', 8, 'insertText'));
show('fill 15051990', onInput('', '15051990', 8, 'insertText'));
show('fill abc', onInput('', 'abc', 3, 'insertText'));
show('fill 1990-05-15', onInput('', '1990-05-15', 10, 'insertText'));
show('type a at end', onInput('15', '15a', 3, 'insertText'));
show('type / mid', onInput('15/05/199', '15//05/199', 3, 'insertText'));
show('type 5/ ', onInput('5', '5/', 2, 'insertText'));
