const { chromium } = require('@playwright/test');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage();
  await p.setContent('<input id=i maxlength=6>');
  await p.evaluate(() => {
    const el = document.getElementById('i'); window.log = []; window.model = [];
    let composing = false;
    const san = () => { const raw = el.value; const t = raw.replace(/[^A-Za-z0-9]/g,'').toUpperCase(); if (t===raw) return; el.value=t; el.setSelectionRange(t.length,t.length); };
    el.addEventListener('input', e => { log.push('input c='+e.isComposing+' '+el.value); if (composing || e.isComposing) return; san(); }, {capture:true});
    el.addEventListener('compositionstart', () => { composing = true; log.push('cstart'); });
    el.addEventListener('compositionend', () => { composing=false; log.push('cend '+el.value); san(); el.dispatchEvent(new Event('input',{bubbles:true})); });
    el.addEventListener('input', () => model.push(el.value));
  });
  const cdp = await p.context().newCDPSession(p);
  async function run(label, steps, commit) {
    await p.evaluate(() => { const el=document.getElementById('i'); el.value=''; log.length=0; model.length=0; el.focus(); });
    for (const t of steps) await cdp.send('Input.imeSetComposition', { text: t, selectionStart: t.length, selectionEnd: t.length });
    await cdp.send('Input.insertText', { text: commit });
    const r = await p.evaluate(() => ({ v: document.getElementById('i').value, log: log.join(' | '), model: model.slice(-1)[0], caret: document.getElementById('i').selectionStart }));
    console.log(label, JSON.stringify(r));
  }
  await run('abc', ['a','ab','abc'], 'abc');
  await run('ab-1', ['a','ab','ab-','ab-1'], 'ab-1');
  await run('deadkey', ['´'], 'é');
  // composition after existing text, mid caret
  await p.evaluate(() => { const el=document.getElementById('i'); el.value='XY'; el.setSelectionRange(1,1); log.length=0; model.length=0; });
  for (const t of ['a','ab']) await cdp.send('Input.imeSetComposition', { text: t, selectionStart: t.length, selectionEnd: t.length });
  await cdp.send('Input.insertText', { text: 'ab' });
  console.log('mid', JSON.stringify(await p.evaluate(() => ({ v: document.getElementById('i').value, caret: document.getElementById('i').selectionStart, model: model.slice(-1)[0] }))));
  await b.close();
})().catch(e => { console.error(e); process.exit(1); });
"

