const { chromium } = require('@playwright/test');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage();
  await p.goto('http://localhost:8080/co/datos');
  const box = p.getByLabel(/^\s*Fecha de nacimiento/).and(p.locator('input'));
  await box.waitFor();
  await p.evaluate(() => { const el = document.getElementById('field-birthDate'); window.__log=[]; 
    const d = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');
    Object.defineProperty(el,'value',{get(){return d.get.call(this)}, set(v){ window.__log.push('set value '+JSON.stringify(v)+' from '+JSON.stringify(d.get.call(this))+' caret '+this.selectionStart); d.set.call(this,v);} });
    el.addEventListener('input', e => window.__log.push('input '+e.inputType+' '+JSON.stringify(d.get.call(el))+' caret '+el.selectionStart), true);
    document.addEventListener('selectionchange', () => window.__log.push('selchange '+el.selectionStart));
  });
  await box.focus(); await box.pressSequentially('15/05/1990');
  for (let i=0;i<5;i++) await p.keyboard.press('ArrowLeft');
  await p.evaluate(() => window.__log.length=0);
  await p.keyboard.press('Backspace');
  const st = () => p.evaluate(() => { const el=document.getElementById('field-birthDate'); return { v: el.value, c: el.selectionStart, active: document.activeElement?.id || document.activeElement?.tagName }; });
  console.log('after BS', JSON.stringify(await st()));
  await p.waitForTimeout(300);
  console.log('after 300ms', JSON.stringify(await st()));
  await p.keyboard.press('End');
  console.log('after End', JSON.stringify(await st()));
  await p.waitForTimeout(300);
  console.log('after End+300', JSON.stringify(await st()));
  await p.keyboard.press('Tab');
  await p.waitForTimeout(300);
  console.log('after Tab', JSON.stringify(await st()), await p.evaluate(() => { const el=document.getElementById('field-birthDate'); return el.getAttribute('aria-invalid')+' | '+(el.getAttribute('aria-describedby')||'').split(' ').map(id=>document.getElementById(id)?.textContent?.trim()).join(' / '); }));
  console.log(JSON.stringify(await p.evaluate(() => window.__log), null, 0));
  console.log('store', await p.evaluate(() => sessionStorage.getItem('quote-wizard')));
  await b.close();
})().catch(e => { console.error(e.message); process.exit(1); });
"

